import{_ as s,a0 as o,w as u,s as p,ao as d,I as l,x as t,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Kubernetes 部署的可視化地圖 | LCTT x X-CMD","titleTemplate":false,"description":"Kubernetes 部署的可視化地圖 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kubernetes 部署的可視化地圖 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kubernetes 部署的可視化地圖 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220228 A visual map of a Kubernetes deployment","title":"Kubernetes 部署的可視化地圖","tag":"202203","desc":""},"relativePath":"202203/20220228 A visual map of a Kubernetes deployment.md","filePath":"[post].md"}'),i={name:"202203/20220228 A visual map of a Kubernetes deployment.md"};function b(m,e,f,y,h,P){const r=o("Link");return u(),p("div",null,[e[15]||(e[15]=d('<h1 id="kubernetes-部署的可視化地圖" tabindex="-1">Kubernetes 部署的可視化地圖 <a class="header-anchor" href="#kubernetes-部署的可視化地圖" aria-label="Permalink to “Kubernetes 部署的可視化地圖”">​</a></h1><blockquote><p>通過查看創建一個吊艙或一個部署時的 10 個步驟，可以更好地瞭解 Kubernetes。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/01/095801szxq9lx5prdqkb5y.jpg" alt=""></p><p>當你在 Kubernetes 上使用容器時，你經常把應用程序組合在一個<ruby>吊艙<rt>pod</rt></ruby>中。當你把一個容器或一個吊艙發佈到生產環境中時，它被稱為一個<ruby>部署<rt>deployment</rt></ruby>。如果你每天甚至每週都在使用 Kubernetes，你可能已經這樣做過幾百次了，但你有沒有想過，當你創建一個吊艙或一個部署時到底會發生什麼？</p><p>我發現在高層次上了解事件鏈條是有幫助的。當然，你不一定要理解它。即使你不知道為什麼，它仍然在工作。我不打算列出每一件發生的小事，但我的目標是涵蓋所有重要的事情。</p><p>這裏有一張 Kubernetes 不同組件如何互動的視覺地圖。</p><p><img src="https://opensource.com/sites/default/files/uploads/pod-chain_0.png" alt="吊艙鏈條" title="Pod chain"></p><p>你可能注意到，在上圖中，我沒有包括 etcd。API 服務器是唯一能夠直接與 etcd 對話的組件，而且只有它能夠對 etcd 進行修改。因此，你可以認為 etcd 在這張圖中存在於（隱藏的）API 服務器後面。</p><p>另外，我在這裏只講到了兩個主要的控制器（<ruby>部署控制器<rt>Deployment controller</rt></ruby>和<ruby>複製集控制器<rt>ReplicaSet controller</rt></ruby>）。其他的控制器的工作方式類似。</p><p>下面的步驟描述了當你執行 <code>kubectl create</code> 命令時會發生什麼。</p><h3 id="步驟-1" tabindex="-1">步驟 1 <a class="header-anchor" href="#步驟-1" aria-label="Permalink to “步驟 1”">​</a></h3><p>當你使用 <code>kubectl create</code> 命令時，一個 HTTP POST 請求被髮送到 API 服務器，其中包含部署清單。API 服務器將其存儲在 etcd 數據存儲中，並返回一個響應給 <code>kubectl</code>。</p><h3 id="步驟-2-和-3" tabindex="-1">步驟 2 和 3 <a class="header-anchor" href="#步驟-2-和-3" aria-label="Permalink to “步驟 2 和 3”">​</a></h3><p>API 服務器有一個觀察機制，所有觀察它的客户都會得到通知。客户端通過打開與 API 服務器的 HTTP 連接來觀察變化，API 服務器會流式地發出通知。其中一個客户端是部署控制器。部署控制器檢測到一個<ruby>部署<rt>Deployment</rt></ruby>對象，它用部署的當前規格創建一個<ruby>複製集<rt>ReplicaSet</rt></ruby>。該資源被送回 API 服務器，並存儲在 etcd 數據存儲中。</p><h3 id="步驟-4-和-5" tabindex="-1">步驟 4 和 5 <a class="header-anchor" href="#步驟-4-和-5" aria-label="Permalink to “步驟 4 和 5”">​</a></h3><p>與上一步類似，所有觀察者都會收到關於 API 服務器中的變化的通知。這一次，複製集控制器會接收這一變化。該控制器瞭解所需的副本數量和對象規格中定義的吊艙選擇器，創建吊艙資源，並將這些信息送回 API 服務器，存儲在 etcd 數據存儲中。</p><h3 id="步驟-6-和-7" tabindex="-1">步驟 6 和 7 <a class="header-anchor" href="#步驟-6-和-7" aria-label="Permalink to “步驟 6 和 7”">​</a></h3><p>Kubernetes 現在擁有運行吊艙所需的所有信息，但吊艙應該在哪個節點上運行？<ruby>調度器<rt>Scheduler</rt></ruby>觀察那些還沒有分配到節點的吊艙，並開始對所有節點進行過濾和排序，以選擇最佳節點來運行吊艙。一旦節點被選中，該信息將被添加到吊艙規格中。而且它被送回 API 服務器並存儲在 etcd 數據存儲中。</p><h3 id="步驟-8、9-和-10" tabindex="-1">步驟 8、9 和 10 <a class="header-anchor" href="#步驟-8、9-和-10" aria-label="Permalink to “步驟 8、9 和 10”">​</a></h3><p>到目前為止的所有步驟都發生在<ruby>控制平面<rt>control plane</rt></ruby>本身。<ruby>工作節點<rt>worker node</rt></ruby>還沒有做任何工作。不過，吊艙的創建並不是由控制平面處理的。相反，在所有節點上運行的 <code>kubelet</code> 服務觀察 API 服務器中的吊艙規格，以確定它是否需要創建任何吊艙。在調度器選擇的節點上運行的 kubelet 服務獲得吊艙規格，並指示工作節點上的容器運行時創建容器。這時就會下載一個容器鏡像（如果它還不存在的話），容器就會實際開始運行。</p><h3 id="理解-kubernetes-的部署" tabindex="-1">理解 Kubernetes 的部署 <a class="header-anchor" href="#理解-kubernetes-的部署" aria-label="Permalink to “理解 Kubernetes 的部署”">​</a></h3><p>對這個一般流程的理解可以幫助你理解 Kubernetes 中的許多事件。考慮一下 Kubernetes 中的<ruby>守護進程集<rt>DaemonSet</rt></ruby>或<ruby>狀態集<rt>StatefulSet</rt></ruby>。除了使用不同的控制器外，吊艙的創建過程是一樣的。</p><p>課後作業：如果部署被修改為有三個應用程序的副本，導致創建吊艙的事件鏈條會是什麼樣子？你可以參考圖表或列出的步驟，但你肯定有你需要弄清楚的知識。知識就是力量，你現在有了瞭解 Kubernetes 的一個重要組成部分。</p><hr>',24)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),a(r,{href:"https://opensource.com/article/22/3/visual-map-kubernetes-deployment"},{default:n(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/22/3/visual-map-kubernetes-deployment",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=t("作者：",-1)),a(r,{href:"https://opensource.com/users/nivedv"},{default:n(()=>[...e[2]||(e[2]=[t("Nived Velayudhan",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const x=s(i,[["render",b]]);export{k as __pageData,x as default};
